from __future__ import absolute_import
import logging
from selenium.webdriver.common.by import By
from taf.selenium.mobile.sbts.pages.modals import LegalNoticeModal


class LoginPage(object):
    def __init__(self, tool):
        self._tool = tool

    def _insert_username(self, locator, username, timeout=60):
        self._tool.insert_text_to_enable_element(locator, username, timeout)

    def _insert_password(self, locator, password, timeout=60):
        self._tool.insert_text_to_enable_element(locator, password, timeout)

    def _click_login_button(self, locator, timeout=60):
        self._tool.click_enabled_element(locator, timeout)


class SbtsLoginManagementPage(LoginPage):
    """
    A class manages login page, login function included.
    """
    INPUT_USERNAME_XPATH = '//input[@name="userName"]'
    INPUT_PASSWORD_XPATH = '//input[@name="password"]'
    LOGIN_BUTTON_XPATH = '//*[contains(@class, "container")]//*[@*="Login"]'
    APP_MAIN_MENU_XPATH = '//div[@class="app-name-mob"]/i'
    APP_USER_ACCOUNT_MENU_XPATH = '//div[@class="menu-container"]//div[contains(text(), "Nemuadmin")]'
    APP_LOGOUT_BUTTON_XPATH = '//div[contains(text(), "Logout")]'

    def __init__(self, tool):
        super(SbtsLoginManagementPage, self).__init__(tool)
        self._legal_notice_modal = LegalNoticeModal(tool)

    def login(self, url, username, password, timeout=60):
        """
        Login into sbts.
        :param url: str, url to sbts web
        :param username: str, username
        :param password: str, password
        :param timeout: int, timeout
        """
        try:
            self._tool.driver.get(url)
            self._insert_username((By.XPATH, self.INPUT_USERNAME_XPATH), username, timeout)
            self._insert_password((By.XPATH, self.INPUT_PASSWORD_XPATH), password, timeout)
            self._click_login_button((By.XPATH, self.LOGIN_BUTTON_XPATH), timeout)

            self._legal_notice_modal.wait_until_legal_notice_modal_appear(timeout)
            self._legal_notice_modal.confirm()
            logging.info('WebUI login successfully.')
        except Exception:
            self._tool.save_screenshot('login', self._tool.screenshot_dir)
            self._tool.close_browser()
            raise

    def logout(self, timeout=60):
        """
        Logout from selenium_sbts web.
        :param timeout: int, timeout
        """
        try:
            self._tool.wait_until_element_is_clickable(self.APP_MAIN_MENU_XPATH)
            self._tool.click_enabled_element_after_visible((By.XPATH, self.APP_MAIN_MENU_XPATH), timeout)
            self._tool.wait_until_element_is_clickable(self.APP_USER_ACCOUNT_MENU_XPATH)
            self._tool.click_enabled_element_after_visible((By.XPATH, self.APP_USER_ACCOUNT_MENU_XPATH), timeout)
            self._tool.wait_until_element_is_clickable(self.APP_LOGOUT_BUTTON_XPATH)
            self._tool.click_enabled_element_after_visible((By.XPATH, self.APP_LOGOUT_BUTTON_XPATH), timeout)
            logging.info('WebUI logout successfully.')
        except Exception:
            self._tool.save_screenshot('logout', self._tool.screenshot_dir)
            raise


class LabAccessLoginManagementPage(LoginPage):
    DC_LAB_USERNAME_FORMAT = '@nsn-intra'
    LAB_ACCESS_INPUT_USERNAME_XPATH = '//input[@id="user" or @id="username"]'
    LAB_ACCESS_INPUT_PASSWORD_XPATH = '//input[@id="passwd" or @id="password"]'
    LAB_ACCESS_SIGN_IN_XPATH = '//input[@type="submit"]'
    LAB_ACCESS_LOGOUT_BUTTON_XPATH = '//td[@id="SignOutbg"]'

    def __init__(self, tool):
        super(LabAccessLoginManagementPage, self).__init__(tool)

    def login(self, url, username, password, timeout=60):
        self._tool.driver.get(url)
        self._insert_username((By.XPATH, self.LAB_ACCESS_INPUT_USERNAME_XPATH), username, timeout)
        self._insert_password((By.XPATH, self.LAB_ACCESS_INPUT_PASSWORD_XPATH), password, timeout)
        self._click_login_button((By.XPATH, self.LAB_ACCESS_SIGN_IN_XPATH), timeout)

        if self.DC_LAB_USERNAME_FORMAT in username:
            self._tool.wait_for_visibility((By.XPATH, self.LAB_ACCESS_LOGOUT_BUTTON_XPATH), timeout)
        self._tool.switch_to_coam_login_tab()
